/* syrk.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syrk.h"

/* --------------------------------------------------------------------
 * Tunable parameters for the optimized kernel.
 * ------------------------------------------------------------------*/

/* Minimal estimated amount of work (in FLOP-equivalents) before
 * enabling multi-threading. Can be tuned for a given machine. */
#ifndef SYRK_OMP_MIN_WORK
# define SYRK_OMP_MIN_WORK (1LL * 128 * 128 * 128)
#endif


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Introduce restrict-qualified local aliases for A and C to
     help the compiler with alias analysis and vectorization.
   - Reorder computation so that each C[i][j] is computed using a
     local accumulator:
         tmp = beta * C[i][j];
         tmp += sum_k alpha * A[i][k] * A[j][k];
         C[i][j] = tmp;
     This preserves the original floating-point operation sequence
     per element (including where alpha is multiplied), but keeps
     the running sum in a register instead of repeatedly writing
     to memory.
   - Access A by rows (k as the innermost loop) to improve spatial
     locality and enable efficient SIMD vectorization.
   - Parallelize the outer loop on i with OpenMP. Each iteration
     writes to a disjoint row of C (only j <= i), so there are no
     write conflicts. The if-clause avoids threading overhead for
     very small problems.
*/
static __attribute__((flatten, noinline))
void kernel_syrk(int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  /* Create local restrict-qualified aliases with explicit leading
   * dimensions. This makes the aliasing and indexing clearer for
   * the optimizer and helps autovectorization. */
  DATA_TYPE (*restrict C_)[n] = C;
  DATA_TYPE (*restrict A_)[m] = A;

  /* Rough estimate of total work. Used only to decide whether to
   * spawn threads (does not affect numerical results). */
  const long work = (long)n * (long)n * (long)m;

  // BLAS PARAMS
  // TRANS = 'N'
  // UPLO  = 'L'
  // =>  Form  C := alpha*A*A**T + beta*C.
  // A is NxM
  // C is NxN
#pragma scop
  /* Parallelize over rows of C (index i). Each iteration of this
   * loop updates a distinct set of elements C[i][0..i], so there
   * are no data races between threads. */
#pragma omp parallel for private(j, k) schedule(dynamic) if (work >= SYRK_OMP_MIN_WORK)
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *restrict Ci = C_[i];
    DATA_TYPE *restrict Ai = A_[i];

    /* Only update the lower-triangular part: j <= i. */
    for (j = 0; j <= i; j++) {
      DATA_TYPE *restrict Aj = A_[j];

      /* Start from beta-scaled original value of C[i][j].
       * This exactly preserves the original arithmetic order:
       *   C[i][j] <- beta * C[i][j];
       *   for k: C[i][j] += alpha * A[i][k] * A[j][k]; */
      DATA_TYPE sum = Ci[j] * beta;

      /* Dot product between row i and row j of A.
       * k is the innermost loop so A[i][k] and A[j][k] are accessed
       * with unit stride, which is cache-friendly and vectorizable.
       *
       * The OpenMP 'simd' directive (if enabled at compile time)
       * enforces vectorization and declares 'sum' as a reduction
       * variable over the k dimension. Without OpenMP, this pragma
       * is ignored and the loop remains a normal inner loop. */
#pragma omp simd reduction(+:sum)
      for (k = 0; k < _PB_M; k++) {
        sum += alpha * Ai[k] * Aj[k];
      }

      /* Write back the final value. */
      Ci[j] = sum;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}

