/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  /* Create restrict-qualified aliases for the 2D arrays.
     POLYBENCH_2D expands to a VLA type (DATA_TYPE C[n][n], etc.).
     Using explicit pointer aliases with restrict helps the compiler
     with alias analysis and enables better vectorization. */
  DATA_TYPE (* restrict C_)[n] = C;
  DATA_TYPE (* restrict A_)[m] = A;

  /* Use the PolyBench loop bounds (may differ from raw n/m in some
     configurations) but keep the full logical sizes for indexing. */
  const int n_ = _PB_N;
  const int m_ = _PB_M;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

//BLAS PARAMS
//TRANS = 'N'
//UPLO  = 'L'
// =>  Form  C := alpha*A*A**T + beta*C.
//A is NxM
//C is NxN
#pragma scop
  /* Optimized algorithm:
     - Parallelize over i (rows of C).  Each (i,j) with j <= i is
       written exactly once, so there are no cross-iteration races.
     - For each (i,j) we fuse the original "scale by beta" and
       "accumulate over k" steps into a single j-loop, so that every
       C[i][j] element is loaded and stored only once.
     - The inner loop is over k (the contiguous dimension in row-major
       layout), which improves cache locality for A and enables
       efficient SIMD code generation.
     - For each (i,j) the sequence of floating-point operations is
       preserved: one multiplication by beta followed by additions over
       k = 0..m-1 in increasing order, exactly as in the original code.
  */
#ifdef _OPENMP
  #pragma omp parallel for private(j, k) schedule(static)
#endif
  for (i = 0; i < n_; i++) {

    DATA_TYPE * restrict Ci = C_[i];
    DATA_TYPE * restrict Ai = A_[i];

    /* Only the lower triangular part (j <= i) is updated, matching the
       original algorithm and the BLAS syrk semantics for UPLO='L'. */
    for (j = 0; j <= i; j++) {

      DATA_TYPE * restrict Aj = A_[j];

      /* Start from beta * C[i][j] (equivalent to the separate scaling
         loop in the original code). */
      DATA_TYPE cij = Ci[j] * beta_;

      /* Accumulate alpha * A[i][k] * A[j][k] over k.
         The loop over k is kept innermost to ensure unit-stride access
         to A's rows. The accumulation proceeds in the same order as
         the original code (k = 0..m_-1), preserving rounding behavior. */
      for (k = 0; k < m_; k++) {
        cij += alpha_ * Ai[k] * Aj[k];
      }

      Ci[j] = cij;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
