/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  /* Cache the dynamic dimensions locally to avoid repeated loads. */
  const int n_ = n;
  const int m_ = m;

  /* Flatten the 2D arrays into 1D, restrict-qualified views.
     - C and A are allocated independently by PolyBench, so they
       never alias each other.
     - Using a flat, restrict-qualified pointer helps the compiler
       generate tighter address arithmetic and better vectorized code. */
  DATA_TYPE * restrict Cdata = &C[0][0];
  DATA_TYPE * restrict Adata = &A[0][0];

//BLAS PARAMS
//TRANS = 'N'
//UPLO  = 'L'
// =>  Form  C := alpha*A*A**T + beta*C.
//A is NxM
//C is NxN
#pragma scop
  /* Each iteration of the outer i-loop updates only the lower
     triangular part of row i of C (C[i][0..i]). Different values of
     i touch disjoint subsets of C, so the iterations are independent
     and can be executed in parallel. */
#pragma omp parallel for private(j, k) schedule(static)
  for (i = 0; i < _PB_N; i++) {

    /* Precompute row offsets for C and A. */
    const int Ci_offset = i * n_;
    const int Ai_offset = i * m_;

    /* Temporary buffer for the scaled row alpha * A[i][:].
       This avoids recomputing alpha * A[i][k] for each (i,j,k)
       triplet, reducing the total number of multiplications while
       preserving the arithmetic expression for each C[i][j].

       Size is m_ (full width), but only the first _PB_M entries are
       actually used. On typical PolyBench problem sizes this buffer
       is small enough to fit comfortably in L1/L2 cache. */
    DATA_TYPE Ai_scaled_row[m_];
    DATA_TYPE * restrict Ai_scaled = Ai_scaled_row;

    /* Compute alpha * A[i][k] once for this row i. */
    {
      const DATA_TYPE * restrict Ai_row = Adata + Ai_offset;
      for (k = 0; k < _PB_M; k++) {
        Ai_scaled[k] = alpha * Ai_row[k];
      }
    }

    /* Process the lower-triangular part of row i: j = 0..i.
       We fuse the original scaling by beta and the rank-k update
       into a single loop nest to avoid a separate pass over C. */
    for (j = 0; j <= i; j++) {
      const int C_index   = Ci_offset + j;
      const int Aj_offset = j * m_;

      /* Load C[i][j], apply the beta scaling once, and then keep
         the value in a register for the entire dot-product. */
      DATA_TYPE cij = beta * Cdata[C_index];

      /* Pointer to row j of A. Both Ai_scaled and Aj_row are accessed
         with unit stride in the inner k-loop, which is friendly to
         caches and SIMD vectorization. */
      const DATA_TYPE * restrict Aj_row = Adata + Aj_offset;

      /* Dot product over k:
           cij = beta*C[i][j] + sum_k (alpha*A[i][k]*A[j][k])
           -> cij = beta*C[i][j] + sum_k (Ai_scaled[k] * Aj_row[k])
         The order of operations for each C[i][j] is preserved
         (same sequence of k-iterations), so floating-point semantics
         match the original kernel. */
      for (k = 0; k < _PB_M; k++) {
        cij += Ai_scaled[k] * Aj_row[k];
      }

      /* Store the updated element of the lower triangle. The upper
         triangle (j > i) is intentionally left untouched, exactly as
         in the original kernel. */
      Cdata[C_index] = cij;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

