  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++)
      C[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied:
   - Use restrict-qualified local aliases for A and C to help the
     compiler assume non-aliasing and keep values in registers.
   - Reorder the inner loops to compute a dot product over k for each
     pair (i,j), which gives contiguous accesses to A's rows and is
     more cache- and vectorization-friendly.
   - Fuse the original "scale by beta" and "add alpha*A*A^T" loops so
     that each C[i][j] element is loaded, updated, and stored exactly
     once.
   - Preserve the exact per-element arithmetic sequence:
       C[i][j] = beta * C[i][j];
       for k: C[i][j] += alpha * A[i][k] * A[j][k];
     by accumulating into a local scalar `cij` with the same operation
     order over k and writing back at the end.
   - Optionally parallelize over i with OpenMP when available; guarded
     by _OPENMP so that compilation without OpenMP support is clean.
*/
static
void kernel_syrk[[gnu::flatten, gnu::noinline]](int n, int m,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m))
{
  int i, j, k;

  /* Local restrict-qualified aliases improve alias analysis.  We never
     access the matrices through the original C/A parameters below. */
  DATA_TYPE (* restrict C_loc)[n] = C;
  DATA_TYPE (* restrict A_loc)[m] = A;

  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

//BLAS PARAMS
//TRANS = 'N'
//UPLO  = 'L'
// =>  Form  C := alpha*A*A**T + beta*C.
//A is NxM
//C is NxN
#pragma scop
#if defined(_OPENMP)
  /* Parallelize across rows of C.  Each iteration of the i-loop writes
     to a different row i of C and only reads from A, so there are no
     data races. */
  #pragma omp parallel for schedule(static) private(j, k)
#endif
  for (i = 0; i < _PB_N; i++)
  {
    /* Row pointers for faster and clearer access. */
    DATA_TYPE       * restrict Ci = C_loc[i];  /* C row i */
    const DATA_TYPE * restrict Ai = A_loc[i];  /* A row i */

    /* Only update the lower triangular part: j <= i. */
    for (j = 0; j <= i; j++)
    {
      const DATA_TYPE * restrict Aj = A_loc[j]; /* A row j */

      /* Load C[i][j], scale by beta, and keep in a register.
         This preserves the per-element arithmetic of the original:
           C[i][j] *= beta;
           for k: C[i][j] += alpha * A[i][k] * A[j][k];
         but avoids repeated memory traffic on C. */
      DATA_TYPE cij = Ci[j] * beta_local;

      /* Dot product over k with contiguous accesses to Ai[k] and Aj[k].
         The accumulation into `cij` follows the same k-iteration order
         as the original code, so the sequence of floating-point
         operations for each C[i][j] is unchanged. */
      for (k = 0; k < _PB_M; k++)
      {
        cij += alpha_local * Ai[k] * Aj[k];
      }

      /* Single store of the updated element. */
      Ci[j] = cij;
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syrk (n, m, alpha, beta, POLYBENCH_ARRAY(C), POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);

  return 0;
}
